using System.Text.Json;
using PsoBB.Core;

namespace PsoBB.Tests;

/// <summary>
/// Checks the ported address predicates against vectors produced by the original machine code.
/// </summary>
public sealed class AddressPredicatesTests
{
	/// <summary>
	/// Loads the vectors generated by <c>src2/oracle/vectors.py</c> for 0x0051F8D8.
	/// </summary>
	/// <returns>Input value and expected result pairs.</returns>
	public static List<object[]> GoldenVectors()
	{
		string path = Path.Combine(AppContext.BaseDirectory, "Golden", "0051F8D8.json");
		using JsonDocument document = JsonDocument.Parse(File.ReadAllBytes(path));
		List<object[]> rows = [];
		foreach (JsonElement vector in document.RootElement.EnumerateArray())
			rows.Add([(ushort)vector.GetProperty("value").GetInt32(), vector.GetProperty("result").GetInt32() != 0]);
		return rows;
	}

	/// <summary>
	/// The ported predicate returns the same value as the original for every vector.
	/// </summary>
	/// <param name="value">The 16-bit input.</param>
	/// <param name="expected">The original's return value.</param>
	[Theory]
	[MemberData(nameof(GoldenVectors))]
	public void IsBelowPageSizeMatchesTheMachineCode(ushort value, bool expected)
	{
		Assert.Equal(expected, AddressPredicates.IsBelowPageSize(value));
	}
}
